// src/event/sql.ts
import { sqliteTable, text, integer, index, uniqueIndex } from "drizzle-orm/sqlite-core";
var EventSequenceTable2 = sqliteTable("event_sequence", {
  aggregate_id: text().notNull().primaryKey(),
  seq: integer().notNull(),
  owner_id: text()
});
var EventTable2 = sqliteTable("event", {
  id: text().$type().primaryKey(),
  aggregate_id: text().notNull().references(() => EventSequenceTable2.aggregate_id, { onDelete: "cascade" }),
  seq: integer().notNull(),
  created: integer().notNull().default(0),
  type: text().notNull(),
  data: text({ mode: "json" }).$type().notNull()
}, (table) => [
  uniqueIndex("event_aggregate_seq_idx").on(table.aggregate_id, table.seq),
  index("event_aggregate_type_seq_idx").on(table.aggregate_id, table.type, table.seq)
]);

export { EventSequenceTable2, EventTable2 };
